public class StackMapFrameVisitor {
    private StackMapFrame currentFrame;

    public StackMapFrameVisitor() {
        this.currentFrame = new StackMapFrame();
    }

    public int visitFrameStart(final int offset, final int numLocal, final int numStack) {
        currentFrame.setOffset(offset);
        currentFrame.setNumLocal(numLocal);
        currentFrame.setNumStack(numStack);
        currentFrame.setLocals(new ArrayList<>(numLocal));
        currentFrame.setStack(new ArrayList<>(numStack));
        return 0; // Return the index of the next element to be written in this frame
    }

    private static class StackMapFrame {
        private int offset;
        private int numLocal;
        private int numStack;
        private List<Object> locals;
        private List<Object> stack;

        public void setOffset(int offset) {
            this.offset = offset;
        }

        public void setNumLocal(int numLocal) {
            this.numLocal = numLocal;
        }

        public void setNumStack(int numStack) {
            this.numStack = numStack;
        }

        public void setLocals(List<Object> locals) {
            this.locals = locals;
        }

        public void setStack(List<Object> stack) {
            this.stack = stack;
        }
    }

    public static void main(String[] args) {
