import java.io.File;

public class FilenameUtils {
    public static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastUnixPos = filename.lastIndexOf(File.separatorChar);
        int lastWindowsPos = filename.lastIndexOf('\\');
        return Math.max(lastUnixPos, lastWindowsPos);
    }

    public static void main(String[] args) {
        System.out.println(indexOfLastSeparator("foo.txt")); // -1
        System.out.println(indexOfLastSeparator("a/b/c.jpg")); // 5
        System.out.println(indexOfLastSeparator("a/b.txt/c")); // 3
        System.out.println(indexOfLastSeparator("a/b/c")); // 3
        System.out.println(indexOfLastSeparator("a\\b\\c.jpg")); // 5
        System.out.println(indexOfLastSeparator("a\\b.txt\\c")); // 3
        System.out.println(indexOfLastSeparator("a\\b\\c")); // 3
    }
}

