public class HeaderParser {

    private int parseEndOfLine(String headerPart, int end) {
        for (int i = end; i < headerPart.length() - 1; i++) {
            if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
                return i;
            }
        }
        return -1; // Return -1 if no \r\n sequence is found
    }

    public static void main(String[] args) {
        HeaderParser parser = new HeaderParser();
        String header = "Header1: value1\r\nHeader2: value2\r\n";
        int index = parser.parseEndOfLine(header, 0);
        System.out.println("End of line index: " + index);
    }
}

