@Override
public void generateGraph(Graph<V, DefaultEdge> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null || resultMap.size() != 2) {
        throw new IllegalArgumentException("Target graph must be non-null and result map must contain exactly two partitions.");
    }

    V partition1 = resultMap.get("partition1");
    V partition2 = resultMap.get("partition2");

    if (partition1 == null || partition2 == null) {
        throw new IllegalArgumentException("Result map must contain non-null vertices for both partitions.");
    }

    // Assuming the vertices for each partition are stored in lists within the resultMap
    @SuppressWarnings("unchecked")
    Iterable<V> vertices1 = (Iterable<V>) resultMap.getOrDefault("vertices1", List.of());
    @SuppressWarnings("unchecked")
    Iterable<V> vertices2 = (Iterable<V>) resultMap.getOrDefault("vertices2", List.of());

    for (V vertex : vertices1) {
        target.addVertex(vertex);
        for (V otherVertex : vertices2) {
            target.addVertex(otherVertex);
            target.addEdge(vertex, otherVertex);
        }
    }
}

