public class ByteArrayComparator {
    private byte[] internalArray;

    public ByteArrayComparator(byte[] internalArray) {
        this.internalArray = internalArray;
    }

    public boolean equals(final byte[] data, int offset, final int len) {
        if (data == null || internalArray == null) {
            return false;
        }
        if (len < 0 || offset < 0 || offset + len > data.length || len > internalArray.length) {
            return false;
        }
        return Arrays.equals(internalArray, 0, len, data, offset, offset + len);
    }

    public static void main(String[] args) {
        ByteArrayComparator comparator = new ByteArrayComparator(new byte[]{1, 2, 3, 4, 5});
        System.out.println(comparator.equals(new byte[]{0, 1, 2, 3, 4, 5}, 1, 5)); // true
        System.out.println(comparator.equals(new byte[]{1, 2, 3, 4, 5}, 0, 5)); // true
        System.out.println(comparator.equals(new byte[]{1, 2, 3, 4, 5, 6}, 0, 5)); // true
        System.out.println(comparator.equals(new byte[]{1, 2, 3, 4}, 0, 4)); // false
        System.out.println(comparator.equals(new byte[]{1, 2, 3, 4, 5}, 0, 6)); // false
    }
}

