public class SubstringUtil {
    /** 
     * Gets a substring from the specified String avoiding exceptions. 
     */
    public static String sub(String str, int start, int end) {
        if (str == null) {
            return null;
        }
        int len = str.length();
        if (start < 0) {
            start = 0;
        }
        if (end > len) {
            end = len;
        }
        if (start > end) {
            return "";
        }
        return str.substring(start, end);
    }

    public static void main(String[] args) {
        System.out.println(sub("Hello, World!", 7, 12)); // Output: World
        System.out.println(sub("Hello, World!", 0, 5));  // Output: Hello
        System.out.println(sub("Hello, World!", -1, 5)); // Output: Hello
        System.out.println(sub("Hello, World!", 7, 20)); // Output: World!
        System.out.println(sub("Hello, World!", 12, 7)); // Output: (empty string)
        System.out.println(sub(null, 0, 5));            // Output: null
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector(int initialCapacity) {
        this.data = new byte[initialCapacity];
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength == 0) {
            return this;
        }

        int requiredCapacity = length + byteLength;
        if (requiredCapacity > data.length) {
            enlarge(requiredCapacity - data.length);
        }

        if (byteArrayValue == null) {
            Arrays.fill(data, length, length + byteLength, (byte) 0);
        } else {
            System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
        }

        length += byteLength;
        return this;
    }

    private void enlarge(int increment) {
        int newCapacity = Math.max(data.length << 1, data.length + increment);
        data = Arrays.copyOf(data, newCapacity);
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector(10);
        bv.putByteArray(new byte[]{1, 2, 3}, 0, 3);
        bv.putByteArray(null, 0, 2);
        System.out.println(Arrays.toString(bv.data)); // Output: [1, 2, 3, 0, 0, 0, 0, 0, 0, 0]
    }
}

