public class Edge {
    private Edge next;
    private Edge prev;
    private LinkedList<Edge> treeEdgeList;

    public Edge(LinkedList<Edge> treeEdgeList) {
        this.treeEdgeList = treeEdgeList;
    }

    public void removeFromTreeEdgeList() {
        if (prev != null) {
            prev.next = next;
        }
        if (next != null) {
            next.prev = prev;
        }
        if (treeEdgeList.getFirst() == this) {
            treeEdgeList.removeFirst();
        }
        if (treeEdgeList.getLast() == this) {
            treeEdgeList.removeLast();
        }
        treeEdgeList.remove(this);
    }

    public static void main(String[] args) {
        LinkedList<Edge> treeEdgeList = new LinkedList<>();
        Edge edge1 = new Edge(treeEdgeList);
        Edge edge2 = new Edge(treeEdgeList);
        Edge edge3 = new Edge(treeEdgeList);

        treeEdgeList.add(edge1);
        treeEdgeList.add(edge2);
        treeEdgeList.add(edge3);

        edge2.removeFromTreeEdgeList();

        // Verify that edge2 is removed
        System.out.println(treeEdgeList.contains(edge2)); // Should print false
    }
}

import java.util.Properties;

public class PropertyFinder {
    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        return substituteVars(value, props);
    }

    private static String substituteVars(String value, Properties props) {
        StringBuilder result = new StringBuilder();
        int varStart = -1;
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '$' && i + 1 < value.length() && value.charAt(i + 1) == '{') {
                if (varStart == -1) {
                    varStart = i;
                }
            } else if (varStart != -1 && c == '}') {
                String varName = value.substring(varStart + 2, i);
                String varValue = props.getProperty(varName);
                if (varValue != null) {
                    result.append(value, varStart, i + 1).append(varValue);
                } else {
                    result.append(value, varStart, i + 1);
                }
                varStart = -1;
            } else if (varStart == -1) {
                result.append(c);
            }
        }
        if (varStart != -1) {
            result.append(value.substring(varStart));
        }
        return result.toString();
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("greeting", "Hello, ${name}!");
        props.setProperty("name", "World");
        System.out.println(findAndSubst("greeting", props)); // Output: Hello, World!
    }
}

