public class CustomByteArrayOutputStream extends ByteArrayOutputStream {
    @Override
    public void write(final byte b[], final int off, final int len) throws IOException {
        if ((off < 0) || (off > b.length) || (len < 0) || ((off + len) > b.length) || ((off + len) < 0)) {
            throw new IndexOutOfBoundsException();
        } else if (len == 0) {
            return;
        }
        ensureCapacity(count + len);
        System.arraycopy(b, off, buf, count, len);
        count += len;
    }

    public static void main(String[] args) {
        CustomByteArrayOutputStream stream = new CustomByteArrayOutputStream();
        byte[] data = {1, 2, 3, 4, 5};
        try {
            stream.write(data, 1, 3);
            System.out.println(java.util.Arrays.toString(stream.toByteArray()));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.Arrays;

public class SwapUtil {
    /** 
     * Swaps the two elements at the specified indices in the given array.
     * @param <V> the type of elements in the array
     * @param arr the array
     * @param i the index of the first element
     * @param j the index of the second element
     */
    public static final <V> void swap(V[] arr, int i, int j) {
        if (arr == null || i < 0 || j < 0 || i >= arr.length || j >= arr.length) {
            throw new IllegalArgumentException("Invalid array or indices");
        }
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        String[] array = {"apple", "banana", "cherry"};
        System.out.println("Before swap: " + Arrays.toString(array));
        swap(array, 0, 2);
        System.out.println("After swap: " + Arrays.toString(array));
    }
}

