import org.apache.commons.lang3.tuple.Pair;
import org.apache.commons.lang3.tuple.ImmutablePair;
import org.joml.Vector2f;
import org.jbox2d.collision.shapes.Box2D;

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    Vector2f center = box.getCenter();
    float width = box.getWidth();
    float height = box.getHeight();
    float halfWidth = width / 2.0f;

    Box2D leftBox = new Box2D(new Vector2f(center.x - halfWidth / 2.0f, center.y), halfWidth, height);
    Box2D rightBox = new Box2D(new Vector2f(center.x + halfWidth / 2.0f, center.y), halfWidth, height);

    return new ImmutablePair<>(leftBox, rightBox);
}

