import java.lang.reflect.Method;

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String strValue = (String) value;
            if (strValue.length() == 1) {
                return strValue.charAt(0);
            } else {
                throw new IllegalArgumentException("String length must be 1 to convert to Character");
            }
        } else if (value instanceof Number) {
            return (char) ((Number) value).intValue();
        } else {
            throw new IllegalArgumentException("Cannot convert " + value.getClass().getName() + " to Character");
        }
    }
    throw new IllegalArgumentException("Type " + type.getName() + " is not supported for conversion to Character");
}

