import org.jgrapht.Graph;
import org.jgrapht.GraphPath;
import org.jgrapht.graph.GraphWalk;
import java.util.Set;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, new ArrayList<>(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();

    Iterator<E> it = edgeList.iterator();
    E firstEdge = it.next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V currentVertex = graph.getEdgeTarget(firstEdge);

    vertexList.add(startVertex);
    vertexList.add(currentVertex);

    while (it.hasNext()) {
        E edge = it.next();
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (source.equals(currentVertex)) {
            vertexList.add(target);
            currentVertex = target;
        } else if (target.equals(currentVertex)) {
            vertexList.add(source);
            currentVertex = source;
        } else {
            throw new IllegalArgumentException("Edges do not form a valid tour");
        }
    }

    return new GraphWalk<>(graph, startVertex, currentVertex, vertexList, edgeList, 0.0);
}

