import java.util.Stack;

public class FrameStackManager {
    private Stack<String> outputFrameStack = new Stack<>();

    private void pop(final String descriptor) {
        if (descriptor.startsWith("(")) {
            // It's a method descriptor, extract argument types
            int end = descriptor.indexOf(')');
            String argsDescriptor = descriptor.substring(1, end);
            int index = 0;
            while (index < argsDescriptor.length()) {
                char c = argsDescriptor.charAt(index);
                switch (c) {
                    case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                        outputFrameStack.pop();
                        index++;
                        break;
                    case 'D': case 'J':
                        outputFrameStack.pop();
                        outputFrameStack.pop(); // double and long take two slots
                        index++;
                        break;
                    case 'L':
                        // Object type, find the end of the descriptor
                        int semiColonIndex = argsDescriptor.indexOf(';', index);
                        outputFrameStack.pop();
                        index = semiColonIndex + 1;
                        break;
                    case '[':
                        // Array type, skip to the end of the descriptor
                        int arrayEndIndex = index;
                        while (arrayEndIndex < argsDescriptor.length() && argsDescriptor.charAt(arrayEndIndex) == '[') {
                            arrayEndIndex++;
                        }
                        if (arrayEndIndex < argsDescriptor.length() && argsDescriptor.charAt(arrayEndIndex) == 'L') {
                            // Object array, find the end of the descriptor
                            int objectEndIndex = argsDescriptor.indexOf(';', arrayEndIndex);
                            arrayEndIndex = objectEndIndex + 1;
                        } else {
                            arrayEndIndex++; // Primitive array
                        }
                        outputFrameStack.pop();
                        index = arrayEndIndex;
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
            }
        } else {
            // It's a type descriptor, pop one type
            outputFrameStack.pop();
        }
    }

    public static void main(String[] args) {
        FrameStackManager manager = new FrameStackManager();
        manager.outputFrameStack.push("int");
        manager.outputFrameStack.push("double");
        manager.outputFrameStack.push("java/lang/String");
        manager.pop("(IDLjava/lang/String;)V");
        System.out.println(manager.outputFrameStack); // Should be empty
    }
}

