public class FilenameUtils {
    public static int indexOfExtension(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastSeparatorIndex = indexOfLastSeparator(filename);
        int lastDotIndex = filename.lastIndexOf('.');
        if (lastDotIndex == -1 || lastSeparatorIndex > lastDotIndex) {
            return -1;
        }
        return lastDotIndex;
    }

    private static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastUnixPos = filename.lastIndexOf('/');
        int lastWindowsPos = filename.lastIndexOf('\\');
        return Math.max(lastUnixPos, lastWindowsPos);
    }

    public static void main(String[] args) {
        System.out.println(indexOfExtension("foo.txt")); // 3
        System.out.println(indexOfExtension("a/b/c.jpg")); // 5
        System.out.println(indexOfExtension("a/b.txt/c")); // -1
        System.out.println(indexOfExtension("a/b/c")); // -1
    }
}

