import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class ThreadSnapshotParser {

    public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) {
                ThreadSnapshot snapshot = parseLineToThreadSnapshot(line);
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (snapshot.getTimestamp() >= range.getStartTime() && snapshot.getTimestamp() <= range.getEndTime()) {
                        threadSnapshots.add(snapshot);
                        break;
                    }
                }
            }
        }
        return threadSnapshots;
    }

    private static ThreadSnapshot parseLineToThreadSnapshot(String line) {
        // Assuming the line format is "timestamp,threadId,state,stackTrace"
        String[] parts = line.split(",");
        long timestamp = Long.parseLong(parts[0]);
        int threadId = Integer.parseInt(parts[1]);
        String state = parts[2];
        String stackTrace = parts[3];
        return new ThreadSnapshot(timestamp, threadId, state, stackTrace);
    }

    public static class ThreadSnapshot {
        private long timestamp;
        private int threadId;
        private String state;
        private String stackTrace;

        public ThreadSnapshot(long timestamp, int threadId, String state, String stackTrace) {
            this.timestamp = timestamp;
            this.threadId = threadId;
            this.state = state;
            this.stackTrace = stackTrace;
        }

        public long getTimestamp() {
            return timestamp;
        }

        public int getThreadId() {
            return threadId;
        }

        public String getState() {
            return state;
        }

        public String getStackTrace() {
            return stackTrace;
        }
    }

    public static class ProfileAnalyzeTimeRange {
        private long startTime;
        private long endTime;

        public ProfileAnalyzeTimeRange(long startTime, long endTime) {
            this.startTime = startTime;
            this.endTime = endTime;
        }

        public long getStartTime() {
            return startTime;
        }

        public long getEndTime() {
            return endTime;
        }
    }
}
